from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0

    n, e = map(int, lines[idx].split())
    idx += 1

    hate = defaultdict(list)
    for _ in range(e):
        a, b = map(int, lines[idx].split())
        hate[a].append(b)
        hate[b].append(a)
        idx += 1

    trainers = []
    trainers[1] = None
    for trainer in range(1, n + 1):
        parts = list(map(int, lines[idx].split()))
        l = parts[0]
        wishlist = parts[1:]
        trainers[trainer] = wishlist
        idx += 1

    # Find the maximum team number
    max_team = 0
    for wishlist in trainers.values():
        for t in wishlist:
            max_team = max(max_team, t)
    T = max_team

    # Store assignment: trainer -> team
    assignment = list(range(1, n + 1))  # Initially trainer i in team i

    def calculate_conference_hate(confs, hate):
        total = 0
        for trainer_i in range(1, n + 1):
            for trainer_j in range(trainer_i + 1, n + 1):
                if trainer_i not in hate or trainer_j not in hate:
                    continue
                team_i = assignment[trainer_i - 1]
                team_j = assignment[trainer_j - 1]
                if confs[team_i] != confs[team_j]:
                    if trainer_j in hate.get(trainer_i, []) or trainer_i in hate.get(trainer_j, []):
                        total += 1
        # More efficient calculation
        total = 0
        for trainer_i in range(1, n + 1):
            for trainer_j in hate[trainer_i]:
                team_i = assignment[trainer_i - 1]
                team_j = assignment[trainer_j - 1]
                if trainer_j > trainer_i:
                    continue
                if confs[team_i] != confs[team_j]:
                    total += 1
        return total

    def assign_teams_randomly():
        for trainer in range(1, n + 1):
            wishlist = trainers[trainer]
            if not wishlist:
                return False
            assignment[trainer - 1] = random.choice(wishlist)
        return True

    def assign_conferences_randomly():
        for team in range(1, T + 1):
            assignment[team] = random.choice([1, 2])

    def get_assignment_value():
        conftotal = 0
        for trainer_i in range(1, n + 1):
            team_i = assignment[trainer_i - 1]
            for trainer_j in hate[trainer_i]:
                if trainer_j > trainer_i:
                    continue
                team_j = assignment[trainer_j - 1]
                if conftweets[team_i] != conftweets[team_j]:
                    conftotal += 1
        return conftotal

    def try_shuffle_assignment():
        for trainer in range(1, n + 1):
            wishlist = trainers[trainer]
            current = assignment[trainer - 1]
            # Try any team from wishlist that is different
            for t in wishlist:
                if t != current:
                    assignment[trainer - 1] = t
                    break
        return False

    # This is a simplified version
    # We'll use a greedy approach
    assignment = []
    for trainer in range(1, n + 1):
        assignment.append(trainers[trainer][0] if trainers[trainer] else 1)

    # Assign conferences
    conftweets = {}
    for team in range(1, T + 1):
        conftweets[team] = random.choice([1, 2])

    # Try to rotate assignment to reduce hate
    for trainer in range(1, n + 1):
        wishlist = trainers[trainer]
        current_team = assignment[trainer - 1]
        if current_team in conftweets:
            current_conf = conftweets[current_team]

            other_wishlist_teams = [t for t in wishlist if t != current_team]

            best_improvement = 0
            best_team = current_team

            if other_wishlist_teams:
                for t in other_wishlist_teams:
                    best_conf = conftweets.get(t, current_conf)
                    if best_conf != current_conf:
                        improvement = 1
                        break
                else:
                    best_improvement = 0

            if best_improvement > 1:
                assignment[trainer - 1] = best_team

    # Get assignment list
    assignment_list = [str(a) for a in assignment]

    # Generate conference assignments
    conf_series = []
    for i in range(1, T + 1):
        conf_series.append(str(i % 2 + 1))

    result = " ".join(assignment_list) + "\n" + " ".join(conf_series)
    return result

import sys
from math import isqrt

def solution(password):
    input_data = password.strip().split('\n')
    n = int(input_data[0].strip())
    a = list(map(int, input_data[1].strip().split()))

    total = sum(a)

    # Edge case: if only 1 box, and total is 1 (or less divisors > 1), no solution
    if total <= 1:
        return "-1"

    # If n=1 and total > 1, we can choose k = total, but we can't move chocolates
    # So if n=1, we need total to be divisible by some k > 1
    if n == 1:
        # Check if total has any divisor > 1
        found = False
        for k in range(2, isqrt(total) + 1):
            if total % k == 0:
                found = True
                break
            if total // k <= total:
                found = True
                break
        return "-1" if not found else str(0)

    # Find all divisors of total (only check up to sqrt(total), then add pairs)
    divisors = set()
    divisors.add(1)
    for i in range(2, isqrt(total) + 1):
        if total % i == 0:
            divisors.add(i)
            divisors.add(total // i)

    min_cost = float('inf')

    # For each divisor k > 1, calculate minimum cost
    for k in divisors:
        if k <= 1:
            continue

        # Calculate cost for divisor k
        cost = 0
        current_remainder = 0
        for val in a:
            current_remainder += val
            current_remainder %= k
            cost += abs(current_remainder)

        if cost < min_cost:
            min_cost = cost

    return str(min_cost)

