def solution(input_str: str) -> str:
    """
    Given n cards with front and back numbers, reorder them so that
    both the front sequence and back sequence are balanced bracket sequences.
    """
    import itertools

    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    cards = []
    for i in range(1, 2 * n + 1):
        a, b = map(int, lines[i].split())
        cards.append((a, b))

    def is_balanced(sequence):
        """Check if sequence is a balanced bracket sequence"""
        stack = []
        for x in sequence:
            if x > 0:
                stack.append(x)
            else:
                if not stack or stack[-1] != abs(x):
                    return False
                stack.pop()
        return len(stack) == 0

    # For n=1, impossible
    if n == 1:
        return "NO"

    # Try permutations for small n
    all_perms = itertools.permutations(range(2 * n))

    for perm in all_perms:
        front = [cards[i][0] for i in perm]
        back = [cards[i][1] for i in perm]

        if is_balanced(front) and is_balanced(back):
            result = []
            for i in perm:
                result.append(f"{cards[i][0]} {cards[i][1]}")
            return "YES\n" + "\n".join(result)

    return "NO"

