    lines = s.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    # Maximum possible height without any strikes
    max_possible = 0
    for h, a in bamboos:
        max_possible = max(max_possible, h + m * a)

    # Binary search for minimum possible maximum
    low = 0
    high = max_possible
    ans = max_possible

    while low <= high:
        mid = (low + high) // 2
        total_needed = 0
        for h, a in bamboos:
            final = h + m * a
            if final > mid:
                excess = final - mid
                # Number of strikes needed: ceil(excess / p)
                total_needed += (excess + p - 1) // p

        if total_needed <= k * m:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(ans)

