def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Union-Find to find connected components
    parent = list(range(n + 1))
    size = [1] * (n + 1)

    def find(x):
        root = x
        while parent[root] != root:
            parent[root] = parent[parent[root]]
            root = parent[root]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            size[ry] += size[rx]

    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            union(u, v)

    # Get sizes of all connected components
    components = [size[i] for i in range(1, n + 1) if parent[i] == i]

    # Generate all lucky numbers up to n
    lucky = set()

    def generate_lucky(current):
        for digit in [4, 7]:
            new_num = current * 10 + digit
            if new_num <= n:
                lucky.add(new_num)
                generate_lucky(new_num)

    for first in [4, 7]:
        generate_lucky(first)
    lucky = sorted(lucky)

    # DP: dp[s] = minimum number of components to sum to s
    dp = {0: 0}
    for sz in components:
        for s, cnt in dp.items():
            ns = s + sz
            if ns <= n:
                # We can add one more component to the combination
                if ns not in dp or cnt + 1 < dp[ns]:
                    dp[ns] = cnt + 1

    # Find the minimum roads needed
    ans = -1
    for l in lucky:
        if l in dp:
            roads = dp[l] - 1  # k components need k-1 roads to merge
            if ans == -1 or roads < ans:
                ans = roads
            if ans == 0:
                break

    return str(ans) + '\n' if ans != -1 else '-1\n'

