def solution(input_str):
    x, y = map(int, input_str.strip().split())

    if y < 0:
        return "0\n"

    if y == 0:
        return "0\n"

    # Get divisors of x for optimization when g stays constant
    divisors = []
    i = 1
    while i * i <= x:
        if x % i == 0:
            divisors.append(i)
            if i * i != x:
                divisors.append(x // i)
        i += 1
    divisors = sorted(list(set(divisors)))

    steps = 0
    current_y = y

    while current_y > 0:
        g = math.gcd(x, current_y)

        if g == 0:
            break

        if g == current_y:
            # current_y divides x exactly, one more step reaches 0
            steps += 1
            break

        # If g doesn't equal current_y, batch appropriately
        # Find how many times we can subtract g before g changes
        if current_y < g * 2:
            # Only one possible step before current_y < g
            steps += 1
            current_y -= g
        else:
            # Find next potential gcd value (largest divisor <= current_y/g)
            threshold = current_y // g
            # Find the largest divisor d <= threshold
            next_val = 1
            for d in divisors:
                if d <= threshold:
                    next_val = d
                elif d > threshold:
                    break

            # Steps until y reaches a multiple of next_val
            if next_val == 1:
                steps += current_y // g
                current_y = 0
            else:
                k = (current_y - next_val) // g
                if k <= 0:
                    steps += 1
                    current_y -= g
                else:
                    steps += k * g // g  # This simplifies to k, but let's be careful
                    current_y -= k * g

    return str(steps) + "\n"

