    for line in lines[1:]:
        parts = line.strip().split()
        if not parts:
            continue
        u, v = int(parts[0]), int(parts[1])
        adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = [[-1] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = collections.deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[start][v] == -1:
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Precompute top 10 sources for each destination
    sources = [[] for _ in range(n + 1)]
    for j in range(1, n + 1):
        d_i_j_list = []
        for i in range(1, n + 1):
            if i != j and dist[i][j] != -1:
                d_i_j_list.append((dist[i][j], i))
        d_i_j_list.sort(reverse=True)
        sources[j] = d_i_j_list[:10]

    # Precompute top 10 destinations for each source
    destinations = [[] for _ in range(n + 1)]
    for k in range(1, n + 1):
        d_k_list = []
        for l in range(1, n + 1):
            if l != k and dist[k][l] != -1:
                d_k_list.append((dist[k][l], l))
        d_k_list.sort(reverse=True)
        destinations[k] = d_k_list[:10]

    max_total = -1
    best = [0, 0, 0, 0]

    # Try all middle pairs (j, k) as second and third cities
    for j in range(1, n + 1):
        for k in range(1, n + 1):
            if j == k:
                continue
            if dist[j][k] == -1:
                continue

            d_jk = dist[j][k]

            for d_ij, i in sources[j]:
                if i == j or i == k:
                    continue

                for d_kl, l in destinations[k]:
                    if l == i or l == j or l == k:
                        continue

                    total = d_ij + d_jk + d_kl
                    if total > max_total:
                        max_total = total
                        best = [i, j, k, l]

    return ' '.join(map(str, best))

