        """Concatenate all numbers from l_val to r_val inclusive"""
        result = l_val
        result_len = len(str(l_val))

        for k in range(l_val + 1, r_val + 1):
            xl = len(str(k))
            result_val = (result * pow_mod(10, xl) + k) % MOD
            result_len += xl
