        # Count which digits k uses
        k_count = {}
        for c in k_str:
            k_count[c] = k_count.get(c, 0) + 1

        # Get remaining digits after removing k
        remain = {}
        for c in freq:
            remain[c] = freq[c] - k_count.get(c, 0)

        # Check if we have enough digits for substring
        possible = True
        digits_to_use = []
        for c in substr_count:
            if substr_count[c] > remain.get(c, 0):
                possible = False
                break
            digits_to_use.extend([c] * substr_count[c])

        if not possible:
            continue

        # Remaining digits for n (excluding those used in substring)
        n_digits = []
        for c in remain:
            count = remain[c] - substring_count.get(c, 0)
            n_digits.extend([c] * count)

        # Filter valid d values
        if len(n_digits) != d:
            continue

        # Sort for smallest number construction
        n_digits.sort()

        # Try placing substring at all positions
        best_for_d = None

        # Determine non-zero digits available
        non_zero = [c for c, cnt in enumerate(digits_to_use) for c_i in range(cnt)]

        for pos in range(d + 1):
            prefix = n_digits[:pos]
            suffix = n_digits[pos:]
            cand = ''.join(prefix) + substring + ''.join(suffix)

            # Skip if leading zero for multi-digit numbers
            if len(cand) == d and d > 1 and cand[0] == '0':
                continue

            if best_for_d is None:
                best_for_d = cand
            else:
                if cand < best_for_d:
                    best_for_d = cand

        if best_for_d:
