from functools import lru_cache

def solution(input_str):
    n, k, m = map(int, input_str.strip().split())
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def count_ways(current_pos, visited_tuple):
        if len(visited_tuple) == k:
            return 1

        visited_set = set(visited_tuple)
        total = 0
        # Try all valid next positions: 1 to min(n, current_pos + m)
        max_y = min(n, current_pos + m)
        for y in range(1, max_y + 1):
            if y not in visited_set:
                total = (total + count_ways(y, visited_tuple + (y,))) % MOD
        return total

    total = 0
    for start in range(1, n + 1):
        total = (total + count_ways(start, (start,))) % MOD

    return str(total)

