        return sum(abs(a[i] - b[i]) for i in range(n))

    def check_coprime(seq):
        for i in range(len(seq)):
            for j in range(i + 1, len(seq)):
                if gcd(seq[i], seq[j]) != 1:
                    return False
        return True

    def backtrack(idx, current_b, current_score):
        nonlocal best_score, best_seq

        if idx == n:
            if current_score < best_score:
                best_score = current_score
                best_seq = current_b[:]
            return

        # Try values in a reasonable range
        for val in range(1, 61):
            # Optimized: val must be coprime with all elements so far
            if is_coprime_with_all(val, current_b):
                current_b.append(val)
                new_score = current_score + abs(a[idx] - val)
                backtrack(idx + 1, current_b, new_score)
                current_b.pop()

    best_score = float('inf')
    best_seq = []

    # Start the search
    backtrack(0, [], 0)

    # Ensure we have a valid result
    if best_seq is None or not check_coprime(best_seq):
        # Fallback: try small range more carefully
        best_seq = []
        for val in range(1, 61):
            if is_coprime_with_all(val, best_seq):
                best_seq.append(val)
                if len(best_seq) == n:
                    break

    return ' '.join(map(str, best_seq)) + ' \n'

