def solution(s):
    lines = s.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Map number to its index
    num_to_idx = {p[i]: i for i in range(n)}

    # Build constraint graph: edge between i and j if they must be in same set
    adj = [[] for _ in range(n)]

    for i in range(n):
        x = p[i]
        # x and (a-x) must be in same set if both exist
        if (a - x) in num_to_idx:
            j = num_to_idx[a - x]
            adj[i].append(j)
            adj[j].append(i)

        # x and (b-x) must be in same set if both exist
        if (b - x) in num_to_idx:
            j = num_to_idx[b - x]
            adj[i].append(j)
            adj[j].append(i)

    # Process each connected component
    visited = [-1] * n  # -1 means unvisited, otherwise stores set assignment
    result = [0] * n

    for i in range(n):
        if visited[i] != -1:
            continue

        # BFS to find component
        stack = [i]
        component = [i]

        while stack:
            u = stack.pop()
            for v in adj[u]:
                if visited[v] == -1:
                    visited[v] = visited[u]
                    stack.append(v)
                    component.append(v)
                elif visited[v] != visited[u]:
                    # Conflict! Same component has conflicting assignments
                    return "NO"

        if visited[i] == -1:  # First node in component
            visited[i] = 1  # Start with set B

        # Now verify all assignments are valid
        for idx in component:
            x = p[idx]
            assigned_set = visited[idx]

            if assigned_set == 1:  # Set B
                if (b - x) not in num_to_idx:
                    return "NO"
                complement = num_to_idx[b - x]
                if visited[complement] != 1:
                    return "NO"
            else:  # Set A
                if (a - x) not in num_to_idx:
                    return "NO"
                complement = num_to_idx[a - x]
                if visited[complement] != 0:
                    return "NO"

        for idx in component:
            result[idx] = visited[idx]

    return "YES\n" + " ".join(map(str, result))

