        parts = line.split()
        if len(parts) >= 2:
            queries.append((int(parts[0]), int(parts[1])))

    if not queries:
        return ""

    max_n = max(n for r, n in queries)
    max_r = max(r for r, n in queries)

    # Sieve to find smallest prime factor for each number
    MIN_PRIME = list(range(max_n + 1))
    for i in range(2, int(max_n**0.5) + 1):
        if MIN_PRIME[i] == i:
            for j in range(i*i, max_n + 1, i):
                if MIN_PRIME[j] == j:
                    MIN_PRIME[j] = i

    # Precompute g table where g[r][k] = f_r(p^k) for any prime p
    # f_0(p^k) = 1 if k=0, else 2
    # f_{r+1}(n) = sum_{d|n} f_r(d), making f_r multiplicative
    MAX_K = 20  # Since 2^19 = 524288 < 10^6 < 2^20
    g = [[0] * (MAX_K + 1) for _ in range(max_r + 1)]

    # f_0(p^k) = 2^ω(p^k) = 2 for k>=1, and 1 for n=1 (k=0)
    for k in range(MAX_K + 1):
        g[0][k] = 1 if k == 0 else 2

    # f_{r+1}(p^k) = sum_{j=0}^k f_r(p^j)
    for r in range(1, max_r + 1):
        cumsum = 0
        for k in range(MAX_K + 1):
            cumsum = (cumsum + g[r-1][k]) % MOD
            g[r][k] = cumsum

    # Process queries
    results = []
    for r, n in queries:
        result = 1
        temp_n = n
        while temp_n > 1:
            p = MIN_PRIME[temp_n]
            count = 0
            while temp_n % p == 0:
                count += 1
                temp_n //= p
            result = (result * g[r][count]) % MOD
        results.append(str(result))

    return '\n'.join(results)

